CREATE TABLE users (
  id INT PRIMARY KEY,          -- cannot be NULL
  email VARCHAR(255) UNIQUE,   -- unique but can be NULL
  username VARCHAR(100) UNIQUE -- multiple UNIQUE constraints OK
);

CREATE TABLE orders (
  id INT PRIMARY KEY,
  status VARCHAR(20) DEFAULT 'pending',
  quantity INT DEFAULT 1,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  is_active BOOLEAN DEFAULT TRUE
);
-- INSERT without status: gets 'pending'
INSERT INTO orders (id) VALUES (1);

CREATE TABLE users (name VARCHAR(100) NOT NULL);

-- Rejected: NULL is not allowed
-- INSERT INTO users VALUES (NULL); -- ERROR

-- Allowed: empty string is a valid non-null value
INSERT INTO users VALUES ('');

-- Check for both NULL and empty string
SELECT * FROM users
WHERE name IS NULL OR name = '';
